package com.sunrise.dentalclinic.controller.api;
import com.sunrise.dentalclinic.dto.*;import com.sunrise.dentalclinic.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController{private final AppointmentService appointments;private final PatientService patients;private final BillingService bills;private final DashboardService dashboard;public ApiController(AppointmentService a,PatientService p,BillingService b,DashboardService d){appointments=a;patients=p;bills=b;dashboard=d;}@GetMapping("/appointments")List<AppointmentResponse> appointments(){return appointments.all().stream().map(AppointmentResponse::from).toList();}@GetMapping("/appointments/{number}")AppointmentResponse appointment(@PathVariable String number){return AppointmentResponse.from(appointments.byNumber(number));}@PostMapping("/appointments")ResponseEntity<AppointmentResponse> createAppointment(@Valid @RequestBody AppointmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(AppointmentResponse.from(appointments.create(r)));}@GetMapping("/patients")List<PatientResponse> patients(@RequestParam(required=false)String q){return patients.search(q).stream().map(PatientResponse::from).toList();}@GetMapping("/patients/{id}")PatientResponse patient(@PathVariable Long id){return PatientResponse.from(patients.get(id));}@PostMapping("/patients")ResponseEntity<PatientResponse> createPatient(@Valid @RequestBody PatientRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(PatientResponse.from(patients.create(r)));}@GetMapping("/bills/{id}")BillResponse bill(@PathVariable Long id){return BillResponse.from(bills.get(id));}@PostMapping("/bills")ResponseEntity<BillResponse> createBill(@RequestParam String appointmentNumber){return ResponseEntity.status(HttpStatus.CREATED).body(BillResponse.from(bills.generate(appointmentNumber)));}@GetMapping("/summary")SummaryResponse summary(){return dashboard.summary();}}
